test('order model：priority 預設 normal、只接受 low / normal / high', () => {
  const svc = createOrderService();
  assert.equal(svc.create(VALID).priority, 'normal');
  for (const priority of ['low', 'normal', 'high']) {
    assert.deepEqual(validateOrder({ ...VALID, priority }), []);
