  const low = svc.create({ ...VALID, priority: 'low' });
  const normal = svc.create(VALID);
  const high = svc.create({ ...VALID, priority: 'high' });
  assert.deepEqual(svc.listByPriority('low').map((o) => o.id), [low.id]);
  assert.deepEqual(svc.listByPriority('normal').map((o) => o.id), [normal.id]);
  assert.deepEqual(svc.listByPriority('high').map((o) => o.id), [high.id]);
  svc.remove(high.id);
  assert.deepEqual(svc.listByPriority('high'), []);
  assert.throws(() => svc.listByPriority('urgent'), /priority/);
});

test('order route：GET /orders/priority/:priority 200、非法優先度 400', () => {
  const routes = orderRoutes();
  routes['POST /orders']({ body: { ...VALID, priority: 'high' } });
  routes['POST /orders']({ body: VALID });
  const res = routes['GET /orders/priority/:priority']({ params: { priority: 'high' } });
  assert.equal(res.status, 200);
  assert.equal(res.body.length, 1);
  assert.equal(res.body[0].priority, 'high');
  assert.equal(routes['GET /orders/priority/:priority']({ params: { priority: 'urgent' } }).status, 400);
  assert.equal(routes['POST /orders']({ body: { ...VALID, priority: 'urgent' } }).status, 400);
});
